query ComparePokemonSpeed($names: [String!]!, $statName: String!, $limit: Int!, $statLimit: Int!) {
  pokemon(where: {name: {_in: $names}}, order_by: {id: asc}, limit: $limit) {
    id
    name
    pokemonstats(where: {stat: {name: {_eq: $statName}}}, limit: $statLimit) {
